/**
 * emit to subscription queries of type FindTermination,
 * but only if the id matches
 *
 * @param		entity	Termination
 */
	protected void emitFindTermination( Termination entity ) {
		LOGGER.info("handling emitFindTermination" );
		
	    queryUpdateEmitter.emit(FindTerminationQuery.class,
	                            query -> query.getFilter().getTerminationId().equals(entity.getTerminationId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllTermination
	 * 
	 * @param		entity	Termination
	 */
	protected void emitFindAllTermination( Termination entity ) {
		LOGGER.info("handling emitFindAllTermination" );
		
	    queryUpdateEmitter.emit(FindAllTerminationQuery.class,
	                            query -> true,
	                            entity);
	}

